import csv
from pathlib import Path

data = [
    ["INC-001", "Database Connection Pool Exhaustion", "The production user-service is throwing 500 Internal Server errors. Monitoring shows that the PostgreSQL database connection pool is completely exhausted, and all new incoming API requests are timing out while waiting for a connection.", "A recent deployment introduced a slow query in the user-authentication path, causing database connections to remain open for 30+ seconds instead of releasing immediately. This cascaded into pool exhaustion.", "Rolled back the deployment to the previous stable version. Added an index to the authentication table to prevent the slow query from occurring again in the future.", "Database", "High", "Production", "Outage"],
    ["INC-002", "Memory Leak / OOMKilled in Payment Service", "Alerts fired for the payment-processing pod constantly crashing and restarting in Kubernetes. Checking the pod events shows OOMKilled (Out of Memory) errors. The memory usage spikes drastically whenever the nightly batch job is submitted.", "The batch processing job was reading the entire payments table into memory at once instead of streaming the rows. This caused the container to exceed its 2GB memory limit.", "Modified the batch job to use a paginated/streaming database cursor and increased the pod memory limit temporarily to 4GB.", "Payment Service", "Critical", "Production", "Performance Degradation"],
    ["INC-003", "Redis Cache Timeout", "Global API response times have degraded by 300% over the last hour. Application logs indicate frequent network read timeouts when the backend attempts to fetch user session data from the Redis cache cluster.", "A noisy neighbor process on the same VM was consuming excessive network bandwidth and CPU, starving the Redis process and causing networking latency spikes.", "Migrated the Redis cluster to dedicated infrastructure and enabled network bandwidth throttling on background workers.", "Cache Layer", "Medium", "Staging", "Performance Degradation"],
    ["INC-004", "Frontend SSL Certificate Expiration", "Users are reporting that they cannot access the main web application. Browsers are displaying a strict warning that the connection is not private due to an expired SSL certificate.", "The automated Let's Encrypt certificate renewal cron job failed silently two weeks ago due to a firewall rule blocking the ACME challenge HTTP requests.", "Updated the firewall rules to allow ACME challenge traffic on port 80. Manually triggered the certbot renewal script and restarted the Nginx reverse proxy.", "Web Server", "High", "Production", "Outage"],
    ["INC-005", "Kafka Message Queue Backlog", "The notification service has stopped sending emails to users. The Kafka consumer lag metric for the 'email-events' topic has spiked to over 500,000 messages and is growing.", "A downstream third-party email provider API was experiencing severe latency, causing the Kafka consumer workers to block for 60 seconds per message and back up the queue.", "Disabled the failing third-party email integration and failed over to the secondary SMTP provider. Increased the number of consumer replicas from 3 to 10 to clear the backlog.", "Message Broker", "High", "Production", "Service Disruption"],
    ["INC-006", "S3 Bucket Permission Denied", "Image uploads in the profile section are failing with 403 Forbidden errors. The backend logs show 'Access Denied' when calling the PutObject API to the AWS S3 bucket.", "An IAM policy update intended for a different application inadvertently removed write permissions for the main application's IAM role to the profile-images bucket.", "Reverted the IAM policy change using Terraform. Added automated policy validation checks in CI/CD to prevent cross-app permission removal.", "Storage", "Medium", "Production", "Feature Failure"],
    ["INC-007", "Elasticsearch Cluster Yellow State", "The logging dashboard is missing recent logs. The Elasticsearch cluster health has degraded to 'Yellow' and indicates that there are unassigned replica shards.", "One of the three data nodes in the cluster ran out of disk space and automatically dropped out of the cluster, leaving replica shards unassigned.", "Expanded the EBS volume size on the affected node from 500GB to 1TB. Resized the filesystem and rejoined the node to the cluster.", "Logging", "Low", "Production", "Infrastructure Issue"],
    ["INC-008", "High CPU on API Gateway", "API Gateway response times have increased significantly. CPU utilization on all Kong gateway nodes is pegged at 100%.", "A sudden influx of malicious bot traffic was executing a highly complex regex matching rule in one of our API Gateway plugins, causing catastrophic backtracking and CPU exhaustion.", "Implemented rate limiting rules based on IP and User-Agent. Rewrote the vulnerable regex pattern in the plugin to avoid catastrophic backtracking.", "API Gateway", "Critical", "Production", "Security/DDoS"],
    ["INC-009", "Stale Data in User Dashboard", "Users are complaining that their account balances are not updating after making a transaction. The database shows the correct balance, but the UI shows stale data.", "The cache invalidation event was failing to publish due to a typo in the event topic name introduced in the last microservice release.", "Corrected the topic name in the microservice configuration and deployed a hotfix. Ran a script to manually clear the stale cache entries.", "Backend API", "High", "Production", "Data Inconsistency"],
    ["INC-010", "DNS Resolution Failure", "Internal microservices are failing to communicate with each other. Logs show 'Temporary failure in name resolution' for all internal service hostnames.", "The CoreDNS pods in the Kubernetes cluster were evicted due to resource constraints on the control plane nodes, causing a cluster-wide DNS outage.", "Scaled up the control plane instances and added priority classes to CoreDNS pods to ensure they are never evicted during resource contention.", "Kubernetes", "Critical", "Production", "Outage"]
]

csv_path = Path("data/incidents/hackathon_dataset.csv")
with open(csv_path, "w", newline="", encoding="utf-8") as f:
    writer = csv.writer(f)
    writer.writerow(["incident_id", "title", "description", "root_cause", "resolution", "component", "severity", "environment", "incident_type"])
    writer.writerows(data)

print(f"Dataset generated at {csv_path.absolute()}")
